from matrix import transpose

def test_empty():
    # Passes before fix
    assert transpose([]) == []

def test_square_matrix():
    # Passes before fix
    sq = [[1, 2], [3, 4]]
    assert transpose(sq) == [[1, 3], [2, 4]]

def test_rectangular_2x3():
    rect = [[1, 2, 3], [4, 5, 6]]
    assert transpose(rect) == [[1, 4], [2, 5], [3, 6]]

def test_single_row():
    assert transpose([[10, 20, 30]]) == [[10], [20], [30]]
